function renderWeaponHonors(d){
  const existing=document.getElementById('condecoracoes-armamentos');if(existing)existing.remove();
  const section=document.createElement('section');section.id='condecoracoes-armamentos';section.className='honors-board weapon-honors';
  const titles=['Ordem da Bateria Principal','Cruz dos Torpedeiros','Medalha da Bateria Secundária','Distinção da Aviação Naval','Medalha de Abalroamento','Distinção de Combate'];
  const icons=["<svg viewBox=\"0 0 72 72\" aria-hidden=\"true\"><path d=\"M13 49h46l-5 10H18zM22 49V35h28v14M27 35V19h6v16M39 35V19h6v16\"/><path d=\"M20 62h32M25 42h22\"/><path d=\"M25 15h10m2 0h10\" stroke-width=\"3\"/></svg>","<svg viewBox=\"0 0 72 72\" aria-hidden=\"true\"><path d=\"M30 49V25q0-11 6-16 6 5 6 16v24l-6 9z\"/><path d=\"M30 43 22 54h8m12-11 8 11h-8M36 58v6M28 64h16M31 25h10\"/><circle cx=\"36\" cy=\"32\" r=\"3\"/></svg>","<svg viewBox=\"0 0 72 72\" aria-hidden=\"true\"><path d=\"M12 49h48l-6 11H18zM19 49V37h14v12M39 49V37h14v12M23 37V25h6v12M43 37V25h6v12M18 63h36\"/><path d=\"M21 21h10m10 0h10\" stroke-width=\"3\"/></svg>","<svg viewBox=\"0 0 72 72\" aria-hidden=\"true\"><path d=\"M36 9c-3 0-4 5-4 9v13L12 42v6l20-5v12l-8 6v3l12-3 12 3v-3l-8-6V43l20 5v-6L40 31V18c0-4-1-9-4-9z\"/><path d=\"M36 20v28M20 43l12-6m20 6-12-6\"/></svg>","<svg viewBox=\"0 0 72 72\" aria-hidden=\"true\"><path d=\"m13 34 14 5 9 19-22-9zM59 34l-14 5-9 19 22-9z\"/><path d=\"M36 12v12m-12-8 6 10m18-10-6 10M36 30v8m-7-6 7 6 7-6M13 61h14m18 0h14\"/></svg>","<svg viewBox=\"0 0 72 72\" aria-hidden=\"true\"><path d=\"M36 10 56 20v20c0 12-20 23-20 23S16 52 16 40V20z\"/><path d=\"m36 23 4 8 9 1-7 6 2 9-8-4-8 4 2-9-7-6 9-1z\"/></svg>"];
  section.innerHTML='<div class="head"><div><div class="eyebrow">Condecorações / Especialistas em armamento</div><h2>O mérito de cada arsenal.</h2></div><p>Maior número de destruições por armamento. Sem mínimo de batalhas; empates recebem a mesma condecoração. Distinções simbólicas da STAR Wise.</p></div><div class="highlights">'+d.weapons.map((w,i)=>{
    const list=[...d.weaponPlayers].sort((a,b)=>b.counts[i]-a.counts[i]||a.name.localeCompare(b.name,'pt-BR'));
    const max=list[0]?.counts[i]||0,leaders=max?list.filter(p=>p.counts[i]===max):[];
    return '<article class="award honor honor-'+i+'"><div class="medal" aria-hidden="true"><div class="ribbon"></div><div class="medal-ring">'+icons[i]+'</div></div><div class="honor-title">'+titles[i]+'</div><small class="honor-citation">'+esc(w[0])+'</small><h3>'+ (leaders.length?leaders.map(p=>esc(p.name)).join(' · '):'Sem medalhista')+'</h3><div class="honor-result"><b>'+num(max)+'</b><small>'+(max?'destruições · '+pct(max/w[1])+' do armamento':'nenhuma destruição registrada')+'</small></div><details class="medal-participants"><summary>Ver participantes <span>'+list.length+' jogadores</span></summary><p class="medal-criteria">Volume total, sem mínimo de batalhas. '+(i===5?'“Sem classificação” é o saldo não atribuído aos cinco tipos da API; não identifica incêndio ou inundação.':i===3?'Conta navios destruídos por aeronaves, não aviões abatidos.':'Dados individuais da temporada.')+'</p><div class="medal-table"><table><caption class="sort-sr">Participantes por armamento — '+esc(w[0])+'</caption><thead><tr><th scope="col">Pos.</th><th scope="col">Jogador</th><th scope="col">Destruições</th><th scope="col">Batalhas</th></tr></thead><tbody>'+list.map(p=>{
      const rank=p.counts[i]>0?list.findIndex(other=>other.counts[i]===p.counts[i])+1:null;
      return '<tr'+(max&&p.counts[i]===max?' class="medal-leader"':'')+'><td>'+(rank?rank+'º':'—')+'</td><td>'+esc(p.name)+'</td><td>'+num(p.counts[i])+'</td><td>'+num(p.battles)+'</td></tr>';
    }).join('')+'</tbody></table></div></details><div class="honor-seal">STAR WISE · T35</div></article>';
  }).join('')+'</div><p class="note">Categorias com total zero permanecem sem medalhista. As condecorações acompanham a sincronização da planilha.</p>';
  document.getElementById('armamentos').after(section);
}

